// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DO MERCADO LIVRE (BUYER, TAXAS ML, SHIPPING)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

const buyer = body.buyer || {};
let rawPhone = (buyer.phone?.number || buyer.phone?.area_code ? `${buyer.phone?.area_code || ''}${buyer.phone?.number || ''}` : '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (buyer.nickname || `${buyer.first_name || 'Comprador'} ${buyer.last_name || 'Mercado Livre'}`).trim();
const clienteEmail = (buyer.email || '').trim().toLowerCase();
const clienteDoc = (buyer.billing_info?.doc_number || '').toString().replace(/\D/g, '');

const numeroPedido = parseInt(body.id || Date.now(), 10);
const valorTotal = parseFloat(body.total_amount || 0);
const status = (body.status || '').toLowerCase();

let statusOperacional = 'Pendente';
if (['paid'].includes(status)) {
  statusOperacional = 'Pago';
} else if (['cancelled'].includes(status)) {
  statusOperacional = 'Cancelado';
}

// Extração de taxas de venda da comissão do Mercado Livre
let totalTaxasML = 0;
const orderItems = (body.order_items || []).map(item => {
  const saleFee = parseFloat(item.sale_fee || 0);
  totalTaxasML += saleFee;
  return {
    produto_nome: item.item?.title || 'Produto Mercado Livre',
    sku: item.item?.seller_custom_field || item.item?.id || 'MLB_SKU',
    quantidade: parseInt(item.quantity || 1, 10),
    preco_unitario: parseFloat(item.unit_price || 0),
    taxa_comissao_ml: saleFee
  };
});

const dedupHash = crypto.createHash('sha256').update(`mercadolivre_${numeroPedido}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    cliente_doc: clienteDoc,
    valor_total: valorTotal,
    taxas_marketplace: totalTaxasML,
    status_operacional: statusOperacional,
    order_items: orderItems,
    shipping_id: body.shipping?.id || ''
  }
}];
